/**
 * Capability gate for the kernel (Janino code generation) tier: <em>no theme query may decline</em>.
 * <p>
 * Every query in the theme catalog is executed at {@link Explanation.Level#Telemetry}, which runs the query and records
 * each strategy rung that refused the plan on the explain tree. The kernel rungs record themselves as {@code irKernel:}
 * and {@code irAggregate:}; this test collects those reasons across all themes and fails while any remain.
 * <p>
 * Two decline reasons are deliberately <b>not</b> capability failures and are excluded:
 * {@code below-threshold-or-pending} (the compile service admits a shape only after it has been seen enough, and
 * compiles asynchronously) and {@code adjacency-unavailable} for stores that genuinely have no view. Each query is
 * warmed repeatedly so the former resolves; if it still appears it is reported separately rather than counted as a
 * capability gap.
 * <p>
 * The dataset is a scaled-down generation of every theme, loaded into one store, mirroring the benchmark store's
 * cross-theme shape (the ANALYTICS theme queries span the other themes' data and generate nothing of their own).
 * Scaling keeps the gate fast; declines recorded here are structural — they come from plan node kinds the lowering does
 * not recognise, which the query's algebra determines, not the data volume.
 */
public class LmdbNativeKernelDeclineCensusTest {

	/** Matches the decline reasons the two kernel rungs record on the explain tree. */
	private static final Pattern KERNEL_DECLINE = Pattern.compile("(irKernel|irAggregate):([^ ,)|]+)");

	/** Declines that mean "not warmed up yet" rather than "cannot do this". */
	private static final Set<String> WARMUP_REASONS = Set.of("below-threshold-or-pending");

	/** Repeats per query, so an asynchronous compile has landed before the reading run. */
	private static final int WARMUP_RUNS = 6;

	/**
	 * Per-run wall-clock cap. {@code explain} defaults to sixty seconds per query
	 * ({@code AbstractParserQuery.DEFAULT_EXPLANATION_EXECUTION_TIMEOUT}); a declining query is by definition one
	 * running its slow interpreted path, so without a cap the census is dominated by the very queries it exists to
	 * find. Declines are recorded when a rung refuses at open time, so a truncated run still reports them.
	 */
	private static final int QUERY_TIMEOUT_SECONDS = 5;

	@TempDir
	static File dataDir;

	private static SailRepository repository;
	private static String previousThreshold;

	@BeforeAll
	static void setUp() {
		previousThreshold = System.getProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			RDFInserter inserter = new RDFInserter(connection);
			ThemeDataSetGenerator.generateMedicalRecords(
					ThemeDataSetGenerator.medicalConfig().withPatientCount(600).withPractitionerCount(600), inserter);
			ThemeDataSetGenerator.generateSocialMedia(
					ThemeDataSetGenerator.socialMediaConfig().withUserCount(900).withPostsPerUser(6), inserter);
			ThemeDataSetGenerator.generateLibrary(
					ThemeDataSetGenerator.libraryConfig()
							.withBookCount(4000)
							.withAuthorCount(1200)
							.withMemberCount(500),
					inserter);
			ThemeDataSetGenerator.generateEngineering(
					ThemeDataSetGenerator.engineeringConfig().withComponentCount(5000).withAssemblyCount(150),
					inserter);
			// Scaled harder than the other themes on purpose. HIGHLY_CONNECTED q12 is `SELECT DISTINCT *` over a
			// two-hop expansion, whose row count grows with the sum over edges of the far endpoint's out-degree — hubs
			// make that superlinear, and the materializing DISTINCT above the kernel then exhausts the fork's heap
			// before the per-query timeout can stop it. Plan shape, which is all this census reads, does not depend on
			// the counts.
			ThemeDataSetGenerator.generateHighlyConnected(
					ThemeDataSetGenerator.highlyConnectedConfig()
							.withNodeCount(400)
							.withHubCount(3)
							.withEdgesPerNode(4),
					inserter);
			ThemeDataSetGenerator.generateTrain(
					ThemeDataSetGenerator.trainConfig()
							.withStationCount(2000)
							.withRouteCount(400)
							.withTrainCount(800),
					inserter);
			ThemeDataSetGenerator.generateElectricalGrid(
					ThemeDataSetGenerator.electricalGridConfig().withSubstationCount(700), inserter);
			ThemeDataSetGenerator.generatePharma(
					ThemeDataSetGenerator.pharmaConfig().withDrugCount(500).withMoleculeCount(750), inserter);
			ThemeDataSetGenerator.generateAdaptiveFilterPlacement(
					ThemeDataSetGenerator.adaptiveFilterPlacementConfig()
							.withProbeCount(2048)
							.withDecoyRouteCount(4096),
					inserter);
			ThemeDataSetGenerator.generateRealEstate(
					ThemeDataSetGenerator.realEstateConfig()
							.withPropertyCount(3000)
							.withAgentCount(300)
							.withDistrictCount(40)
							.withAmenityCount(60),
					inserter);
			connection.commit();
		}
	}

	@AfterAll
	static void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		if (previousThreshold == null) {
			System.clearProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		} else {
			System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", previousThreshold);
		}
	}

	@Test
	void noThemeQueryDeclinesTheKernel() throws IOException {
		Map<String, Set<String>> capabilityDeclines = new TreeMap<>();
		Map<String, Set<String>> warmupDeclines = new TreeMap<>();
		Map<String, List<String>> declinesByPair = new LinkedHashMap<>();
		List<String> failures = new ArrayList<>();

		int pairCount = 0;
		for (Theme theme : Theme.values()) {
			List<String> queries = ThemeQueryCatalog.queriesFor(theme);
			for (int index = 0; index < queries.size(); index++) {
				pairCount++;
				String pair = theme + " q" + index;
				String query = queries.get(index);
				Set<String> reasons;
				long started = System.nanoTime();
				try {
					reasons = declineReasons(query);
				} catch (RuntimeException problem) {
					failures.add(pair + ": " + problem);
					System.out.println(String.format("%-28s FAILED  %s", pair, problem));
					continue;
				}
				System.out.println(String.format("%-28s %5d ms  %s", pair,
						(System.nanoTime() - started) / 1_000_000L,
						reasons.isEmpty() ? "engaged" : String.join(", ", reasons)));
				for (String reason : reasons) {
					String bare = reason.substring(reason.indexOf(':') + 1);
					Map<String, Set<String>> target = WARMUP_REASONS.contains(bare) ? warmupDeclines
							: capabilityDeclines;
					target.computeIfAbsent(reason, key -> new LinkedHashSet<>()).add(pair);
					if (target == capabilityDeclines) {
						declinesByPair.computeIfAbsent(pair, key -> new ArrayList<>()).add(reason);
					}
				}
			}
		}

		String census = renderCensus(pairCount, capabilityDeclines, warmupDeclines, declinesByPair, failures);
		System.out.println(census);
		Files.writeString(censusFile(), census);

		assertThat(failures).as("theme queries that failed to execute").isEmpty();
		assertThat(declinesByPair)
				.as("theme query/kernel pairs still declining (census written to %s):%n%s", censusFile(), census)
				.isEmpty();
	}

	/**
	 * Runs a query at telemetry level and returns the distinct kernel decline reasons it recorded.
	 * <p>
	 * A run is repeated only while the reasons are <em>all</em> warmup reasons, which is the only condition repeating
	 * can clear; a structural decline is returned on the first run rather than paid for {@link #WARMUP_RUNS} times.
	 * Each run is capped by {@link #QUERY_TIMEOUT_SECONDS} because {@code explain} otherwise inherits a sixty-second
	 * default per query, and a census that declines is by construction a census of queries running their slow path.
	 */
	private static Set<String> declineReasons(String query) {
		Set<String> reasons = new LinkedHashSet<>();
		for (int run = 0; run < WARMUP_RUNS; run++) {
			reasons.clear();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				org.eclipse.rdf4j.query.TupleQuery prepared = connection.prepareTupleQuery(query);
				prepared.setMaxExecutionTime(QUERY_TIMEOUT_SECONDS);
				Explanation explanation = prepared.explain(Explanation.Level.Telemetry);
				Matcher matcher = KERNEL_DECLINE.matcher(explanation.toString());
				while (matcher.find()) {
					reasons.add(matcher.group(1) + ":" + matcher.group(2));
				}
			}
			boolean onlyWarmup = !reasons.isEmpty() && reasons.stream()
					.allMatch(reason -> WARMUP_REASONS.contains(reason.substring(reason.indexOf(':') + 1)));
			if (!onlyWarmup) {
				return reasons;
			}
		}
		return reasons;
	}

	private static String renderCensus(int pairCount, Map<String, Set<String>> capabilityDeclines,
			Map<String, Set<String>> warmupDeclines, Map<String, List<String>> declinesByPair,
			List<String> failures) {
		StringBuilder out = new StringBuilder();
		out.append("=== Kernel decline census ===\n");
		out.append("themes=")
				.append(Theme.values().length)
				.append(" pairs=")
				.append(pairCount)
				.append(" declining pairs=")
				.append(declinesByPair.size())
				.append('\n');
		out.append("\n-- capability declines by reason (pair count, then pairs) --\n");
		capabilityDeclines.entrySet()
				.stream()
				.sorted((a, b) -> Integer.compare(b.getValue().size(), a.getValue().size()))
				.forEach(entry -> out.append(String.format("%4d  %-52s %s%n", entry.getValue().size(), entry.getKey(),
						String.join(", ", entry.getValue()))));
		if (capabilityDeclines.isEmpty()) {
			out.append("      (none)\n");
		}
		out.append("\n-- warmup-only declines (not capability gaps) --\n");
		warmupDeclines.forEach((reason, pairs) -> out
				.append(String.format("%4d  %-52s %s%n", pairs.size(), reason, String.join(", ", pairs))));
		if (warmupDeclines.isEmpty()) {
			out.append("      (none)\n");
		}
		if (!failures.isEmpty()) {
			out.append("\n-- queries that failed to execute --\n");
			failures.forEach(failure -> out.append("      ").append(failure).append('\n'));
		}
		return out.toString();
	}

	private static Path censusFile() {
		Path target = Paths.get("target");
		return target.toFile().isDirectory() ? target.resolve("kernel-decline-census.txt")
				: Paths.get("kernel-decline-census.txt");
	}
}
